import{_ as t,o as a,c as I,a0 as l}from"./chunks/framework.DQOulFGV.js";const e="data:image/svg+xml;base64,",s="data:image/svg+xml;base64,",k=JSON.parse('{"title":"第3章 RDB 持久化","description":"","frontmatter":{},"headers":[],"relativePath":"redis/02-standalone-core/chapter-03-rdb.md","filePath":"redis/02-standalone-core/chapter-03-rdb.md"}'),d={name:"redis/02-standalone-core/chapter-03-rdb.md"};function h(g,i,n,r,o,c){return a(),I("div",null,[...i[0]||(i[0]=[l('<h1 id="第3章-rdb-持久化" tabindex="-1">第3章 RDB 持久化 <a class="header-anchor" href="#第3章-rdb-持久化" aria-label="Permalink to &quot;第3章 RDB 持久化&quot;">​</a></h1><blockquote><p>Redis 的数据都在内存里，一旦宕机就全部丢失。RDB（Redis DataBase）通过「快照」把某个时间点的内存数据写到磁盘，实现持久化。本章讲解 RDB 的工作原理、触发方式与优缺点。</p></blockquote><hr><h2 id="_3-1-工作原理" tabindex="-1">3.1 工作原理 <a class="header-anchor" href="#_3-1-工作原理" aria-label="Permalink to &quot;3.1 工作原理&quot;">​</a></h2><p>RDB 把某个时刻的内存数据整体序列化成一个二进制文件（默认 <code>dump.rdb</code>），恢复时直接把这个文件加载回内存。</p><p><img src="'+e+`" alt="RDB 快照与恢复"></p><h3 id="触发方式" tabindex="-1">触发方式 <a class="header-anchor" href="#触发方式" aria-label="Permalink to &quot;触发方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">命令/配置</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">手动保存</td><td style="text-align:left;"><code>SAVE</code></td><td style="text-align:left;">主线程执行，阻塞所有命令</td></tr><tr><td style="text-align:left;">手动后台保存</td><td style="text-align:left;"><code>BGSAVE</code></td><td style="text-align:left;">fork 子进程执行，不阻塞主线程</td></tr><tr><td style="text-align:left;">自动保存</td><td style="text-align:left;"><code>save 900 1</code> 等</td><td style="text-align:left;">满足条件自动触发 BGSAVE</td></tr></tbody></table><p><strong>自动触发配置</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">save</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 900</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 900 秒内至少 1 次写操作</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">save</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 300 秒内至少 10 次写操作</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">save</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 60 秒内至少 10000 次写操作</span></span></code></pre></div><p>满足任意一个条件就触发一次 BGSAVE。</p><blockquote><p><code>SAVE</code> 会阻塞主线程，生产环境禁用；<code>BGSAVE</code> 通过 fork 子进程后台完成，生产环境使用 <code>BGSAVE</code> 或自动触发。</p></blockquote><hr><h2 id="_3-2-fork-与写时复制" tabindex="-1">3.2 fork 与写时复制 <a class="header-anchor" href="#_3-2-fork-与写时复制" aria-label="Permalink to &quot;3.2 fork 与写时复制&quot;">​</a></h2><p>BGSAVE 的核心机制是 <code>fork</code> 与写时复制（Copy-On-Write，COW）。</p><h3 id="fork-子进程" tabindex="-1">fork 子进程 <a class="header-anchor" href="#fork-子进程" aria-label="Permalink to &quot;fork 子进程&quot;">​</a></h3><p><code>fork</code> 让子进程复制父进程的内存页表，得到一个「内存快照」。此时父子进程共享同一份内存，并不实际复制数据。</p><h3 id="写时复制" tabindex="-1">写时复制 <a class="header-anchor" href="#写时复制" aria-label="Permalink to &quot;写时复制&quot;">​</a></h3><p>子进程开始写 RDB 文件后，如果主进程继续处理写命令修改了数据，操作系统会为被修改的内存页创建副本，子进程继续读旧数据，主进程改新数据。</p><p><img src="`+s+`" alt="fork 与写时复制"></p><p>关键点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">概念</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">fork 瞬间</td><td style="text-align:left;">复制页表，速度快，但大内存下仍有短暂停顿</td></tr><tr><td style="text-align:left;">写时复制</td><td style="text-align:left;">只复制被修改的页，不整体复制内存</td></tr><tr><td style="text-align:left;">内存开销</td><td style="text-align:left;">修改越多，额外内存越多；极端情况接近翻倍</td></tr><tr><td style="text-align:left;">大内存风险</td><td style="text-align:left;">内存很大时 fork 可能造成毫秒级到秒级的停顿</td></tr></tbody></table><blockquote><p>fork 停顿是 RDB 的主要副作用。内存越大、fork 越慢，可能造成短暂的服务延迟。这也是大内存实例需要关注的性能点（见第五卷）。</p></blockquote><hr><h2 id="_3-3-配置与优缺点" tabindex="-1">3.3 配置与优缺点 <a class="header-anchor" href="#_3-3-配置与优缺点" aria-label="Permalink to &quot;3.3 配置与优缺点&quot;">​</a></h2><h3 id="常用配置" tabindex="-1">常用配置 <a class="header-anchor" href="#常用配置" aria-label="Permalink to &quot;常用配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dbfilename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump.rdb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # RDB 文件名</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/redis</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 文件保存目录</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rdbcompression</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 是否压缩（LZF 算法）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">save</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 900</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 自动保存策略</span></span></code></pre></div><h3 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to &quot;优缺点&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">优点</td><td style="text-align:left;">文件紧凑、二进制格式加载快（适合灾备恢复）</td></tr><tr><td style="text-align:left;">优点</td><td style="text-align:left;">fork 子进程生成，主进程不阻塞（BGSAVE）</td></tr><tr><td style="text-align:left;">缺点</td><td style="text-align:left;">快照之间宕机会丢失最后一段数据（不实时）</td></tr><tr><td style="text-align:left;">缺点</td><td style="text-align:left;">fork 大内存实例时有停顿风险</td></tr></tbody></table><h3 id="rdb-与-aof-的选择" tabindex="-1">RDB 与 AOF 的选择 <a class="header-anchor" href="#rdb-与-aof-的选择" aria-label="Permalink to &quot;RDB 与 AOF 的选择&quot;">​</a></h3><p>RDB 适合「允许少量数据丢失、看重恢复速度」的场景；AOF 适合「数据完整性优先、可容忍稍慢恢复」的场景。实际生产常用两者结合（混合持久化），见第 4 章。</p>`,31)])])}const m=t(d,[["render",h]]);export{k as __pageData,m as default};
